<script setup lang="ts">
import { computed } from 'vue'
import { assetBusinessLevelLabels, assetCategoryLabels, assetStatutoryCategoryLabels, formatDate, type Asset } from './api'
import type { Activity } from './activity'
import type { RuntimeEvidenceScope } from './runtime-evidence-scope'
import { assessmentFactLabels, assessmentFactSourceLabel, assessmentFactStateLabel, type AssessmentFact } from './assessments'
import { useScenarioContext, type ScenarioTaskData } from './scenario-context'
import { scenarios } from './scenario-navigation'
import { defaultScenarioTasks, scenarioPresentations, scenarioStages } from './scenario-presentation'
import { scenarioCheckOutcomeLabels, scenarioCheckRetestLabels, scenarioCheckReportLabels, type ScenarioCheckFinding, type ScenarioCheckRun } from './scenario-checks'
import { controlStatusLabels } from './security-operations'
import Icon from './Icon.vue'
import ScenarioFactCard from './ScenarioFactCard.vue'
import evidencePack from './assets/scenario-evidence-pack.webp'

const props = defineProps<{ slug: string; scenarioId: string; taskId?: string; data?: ScenarioTaskData | null; asset?: Asset; activity?: Activity; run?: ScenarioCheckRun; runtime?: boolean; runtimeInput?: RuntimeEvidenceScope; editor: boolean; busy?: boolean }>()
const emit = defineEmits<{ finding: [id: string]; remediate: [finding: ScenarioCheckFinding]; export: []; ledger: [view: string]; runtime: [] }>()
const { href } = useScenarioContext(props.slug)
const presentation = computed(() => scenarioPresentations[props.scenarioId + '/' + (props.taskId || defaultScenarioTasks[props.scenarioId])] || scenarioPresentations['governance/inventory']!)
const task = computed(() => scenarios.find(s => s.id === props.scenarioId)?.tasks.find(t => t.id === props.taskId))
const independentRuntime = computed(() => props.runtime || !!props.run?.scope)
const facts = computed(() => independentRuntime.value ? [] : props.data?.facts ?? [])
const scopedAsset = computed(() => independentRuntime.value ? undefined : props.asset)
const adoptedRuntimeScope = computed(() => props.run?.scope || (props.runtime ? props.runtimeInput : undefined))
const activity = computed(() => independentRuntime.value ? undefined : props.activity)
const classification = computed(() => independentRuntime.value ? undefined : props.data?.classification)
const findings = computed(() => props.run?.findings ?? [])
const evidence = computed(() => props.run?.evidence ?? [])
const reports = computed(() => props.run?.reportRequirements ?? [])
const actions = computed(() => props.run?.actions ?? [])
const priority = computed(() => findings.value.find(f => f.outcome === 'non_compliant') || findings.value.find(f => f.outcome === 'needs_verification') || findings.value[0])
const stages = computed(() => scenarioStages(props.run))
const scopeLabel = computed(() => props.run?.scope ? `来源 #${props.run.scope.sourceId} · ${props.run.scope.service}` : independentRuntime.value ? '独立运行时来源 · 尚未运行' : props.run ? `${props.run.assetName || '资产 #' + props.run.assetId}${props.run.activityId ? ' / 活动 #' + props.run.activityId : ''}` : activity.value?.name || scopedAsset.value?.name || classification.value?.item.asset.name || '尚未选择检查范围')
const sortedEvidence = computed(() => [...evidence.value].sort((a,b) => (a.observedAt || '').localeCompare(b.observedAt || '')))
const sourceGroups = computed(() => [...new Set(sortedEvidence.value.map(x => x.source))].map(source => ({ source, records: sortedEvidence.value.filter(e => e.source === source) })))
const materialLabels: Record<string,string> = { auto_filled:'已带入事实', needs_confirmation:'需人工核实', missing:'待补充', not_applicable:'有据不适用' }
const outcomeClass = (value: string) => value === 'compliant' ? 'status-verified' : value === 'non_compliant' ? 'status-needs_work' : 'status-draft'
function factKeys(keys: string[]) { return facts.value.filter(f => keys.includes(f.key)) }
function sourceState(value: string) { return ({ current:'近期有记录', stale:'已过期', never_run:'尚未采集', paused:'已暂停', revoked:'已撤销', failed:'采集失败', observing:'接收中' } as Record<string,string>)[value] || '状态待确认' }
const lanes = computed(() => [
  { name:'输入边界', icon:'assets', keys:['application_data_categories','application_training_use'], description:'允许输入的数据类别与训练使用声明', results:[] as ScenarioCheckFinding[] },
  { name:'知识边界', icon:'classification', keys:['application_knowledge_bases'], description:'知识配置不代表完整检索权限', results:[] as ScenarioCheckFinding[] },
  { name:'输出边界', icon:'reports', keys:['application_retention','application_region'], description:'返回类别、接收范围和输出观察分别核对', results:[] as ScenarioCheckFinding[] },
])
</script>

<template>
  <section class="scenario-visual" :class="'visual-' + presentation.layout" aria-label="当前任务可视化工作区">
    <div class="visual-scope"><div><strong>{{ scopeLabel }}</strong><span v-if="run">运行 #{{ run.id }} · {{ formatDate(run.createdAt) }} · {{ run.engineVersion }}</span><span v-else>当前登记与来源事实 · 尚无本次检查结果</span></div><div class="visual-scope-links"><button class="table-link" type="button" @click="emit('runtime')">调整独立来源</button><button class="table-link" type="button" @click="emit('ledger','history')">回看历史运行<Icon name="audit"/></button></div></div>
    <p v-if="independentRuntime" class="visual-boundary">采用独立运行时来源；下方不采用上方业务资产的登记事实。窗口、主体和接口以本次运行实际 scope 为准。</p>
    <dl v-if="adoptedRuntimeScope" class="visual-runtime-scope"><div><dt>{{ run ? '实际采用来源' : '待运行来源' }}</dt><dd>#{{ adoptedRuntimeScope.sourceId }} · {{ adoptedRuntimeScope.service || '全部获准服务' }}</dd></div><div><dt>接口范围</dt><dd>{{ adoptedRuntimeScope.method || '全部获准方法' }} {{ adoptedRuntimeScope.route || '所列来源下全部获准接口' }}</dd></div><div><dt>主体 / IP</dt><dd>{{ adoptedRuntimeScope.subjectRef || '未限定主体' }} / {{ adoptedRuntimeScope.clientIp || '未限定 IP' }}</dd></div><div><dt>实际时间窗</dt><dd>{{ formatDate(adoptedRuntimeScope.from) }} 至 {{ formatDate(adoptedRuntimeScope.to) }}</dd></div></dl>
    <ol class="visual-stages" aria-label="采用证据与整改阶段"><li v-for="(step,index) in stages" :key="step.label" :class="{'has-record':step.reached}"><span>{{ index + 1 }}</span><div><strong>{{ step.label }}</strong><small>{{ step.state }}</small></div><Icon v-if="index < stages.length-1" name="arrow"/></li></ol>
    <p class="visual-stage-note">各阶段仅表示已返回的记录；执行回执、新来源复测与独立复核不能互相代替。</p>


    <div class="visual-workspace">
      <div class="visual-main">
        <section v-if="presentation.layout === 'personal-chain'" class="visual-panel visual-processing">
          <div class="visual-panel-heading"><h2>当前个人信息处理链</h2><span class="visual-layer">业务登记与来源观察分开</span></div>
          <div class="processing-chain">
            <ScenarioFactCard title="收集与数据范围" icon="assets" :facts="facts" :fact-keys="['source_observed_types','source_coverage','asset_category']"/>
            <ScenarioFactCard title="使用与用途" icon="user" :facts="facts" :fact-keys="['activity_purpose','lawful_basis']"/>
            <ScenarioFactCard title="共享与接收方" icon="activities" :facts="facts" :fact-keys="['activity_recipient','activity_transfer']"/>
            <ScenarioFactCard title="保存与删除" icon="audit" :facts="facts" :fact-keys="['activity_retention','application_retention']" note="安排已登记不表示已执行删除"/>
          </div><div class="visual-purpose-line"><Icon name="arrow"/><span>沿链核对用途、依据与实际观察；缺少同意、权利工单和删除源时保持待核实。</span></div>
        </section>

        <section v-else-if="['controls','audit','permissions'].includes(presentation.layout)" class="visual-panel">
          <div class="visual-panel-heading"><h2>{{ presentation.layout === 'audit' ? '技术审计底稿与依据' : presentation.layout === 'permissions' ? '批准基线与来源权限对照' : '要求与技术证据矩阵' }}</h2><button class="table-link" type="button" @click="emit('ledger','findings')">逐项操作</button></div>
          <p v-if="taskId === 'personal-audit'" class="visual-boundary">此入口复用个人信息审计任务，不能算作第二套审计引擎。</p>
          <div class="visual-table" role="region" tabindex="0" aria-label="要求观察证据对照"><table><thead><tr><th>技术基线与采用依据</th><th>来源观察</th><th>判定</th><th>整改与证据</th></tr></thead><tbody><template v-for="item in findings" :key="item.id"><tr :class="{'is-priority':priority?.id === item.id}"><th><button class="visual-record" type="button" @click="emit('finding',item.id)">{{ item.title }}</button><small>{{ item.basis.clause }} · {{ item.basis.version }}<br>{{ item.ruleVersion }}</small></th><td>{{ item.observed }}<small>{{ item.coverage }}</small></td><td><span class="badge" :class="outcomeClass(item.outcome)">{{ scenarioCheckOutcomeLabels[item.outcome] || item.outcome }}</span></td><td><button class="table-link" type="button" @click="emit('finding',item.id)">{{ item.evidenceRefs.length }} 项证据<Icon name="reports"/></button><small>{{ item.missingConditions.length }} 项待核实条件</small></td></tr><tr v-if="item.id === priority?.id" class="visual-difference"><td colspan="4"><div><section><span>批准 / 核查基线</span><strong>{{ item.expected }}</strong></section><b>VS</b><section><span>本次来源观察</span><strong>{{ item.observed }}</strong></section></div><button v-if="editor && item.remediation.executable && !item.actionId && !actions.some(a => a.findingId === item.id)" class="button button-secondary" type="button" :disabled="busy" @click="emit('remediate',item)">申请受控整改</button><p v-else>{{ item.remediation.advice }}</p></td></tr></template></tbody></table></div><p v-if="!findings.length" class="visual-empty">尚无本次技术判定。选定范围后运行检查，实际采用的基线、观察与证据会逐项列示。</p>
        </section>

        <section v-else-if="presentation.layout === 'transfer'" class="visual-panel">
          <div class="visual-panel-heading"><h2>登记去向与来源观察</h2><a class="table-link" :href="href('data-flows')">调查真实关系<Icon name="external"/></a></div>
          <div class="transfer-declaration"><div><Icon name="assets"/><strong>{{ activity?.assetName || scopedAsset?.name || '源对象待指定' }}</strong><small>业务登记</small></div><span class="declared-line" aria-label="仅登记关系">登记路径<br>⇢</span><div><Icon name="activities"/><strong>{{ activity?.transferPath || '传输路径待核实' }}</strong><small>不代表实际观察链路</small></div><span class="declared-line">登记关系<br>⇢</span><div class="unknown-node"><Icon name="user"/><strong>{{ activity?.recipient || '接收方待核实' }}</strong><small>{{ activity?.region || '地域待核实' }}</small></div></div>
          <p class="visual-boundary">虚线仅表示活动登记，不连接成已证实流向。以下来源引用独立核对，完整关系到数据流转图调查。</p>
          <div class="visual-table" role="region" tabindex="0" aria-label="跨境采用来源"><table><thead><tr><th>采用来源记录</th><th>实际覆盖</th><th>观察时点</th></tr></thead><tbody><tr v-for="record in evidence" :key="record.id"><td>{{ assessmentFactSourceLabel(record.source) }}<small>{{ record.record }}</small></td><td>{{ record.scope }}</td><td>{{ record.observedAt ? formatDate(record.observedAt) : '未提供' }}</td></tr></tbody></table></div><p v-if="!evidence.length" class="visual-empty">尚无本次采用的来源引用，不根据登记地域或接收方推断真实链路或出境规模。</p>
        </section>

        <section v-else-if="presentation.layout === 'coverage'" class="visual-panel">
          <div class="visual-panel-heading"><h2>来源覆盖与能力证据</h2><a class="table-link" :href="href('discovery')">接入或补采<Icon name="external"/></a></div>
          <div class="visual-table" role="region" tabindex="0" aria-label="实际返回的来源能力证据"><table><thead><tr><th>核对维度</th><th>返回事实</th><th>来源记录与时点</th></tr></thead><tbody><tr v-for="key in presentation.keys" :key="key"><th>{{ assessmentFactLabels[key] || key }}</th><td><template v-if="factKeys([key]).length"><span v-for="(fact,index) in factKeys([key])" :key="index" class="visual-evidence-tag">{{ assessmentFactStateLabel(fact) }} · {{ assessmentFactSourceLabel(fact.source) }}</span></template><span v-else class="visual-unknown">未取得</span></td><td><span v-for="(fact,index) in factKeys([key])" :key="index" class="visual-evidence-tag">{{ fact.record || '未提供记录引用' }} · {{ fact.observedAt ? formatDate(fact.observedAt) : '时点未提供' }}</span></td></tr></tbody></table></div>
          <div class="visual-source-register"><h3>工作区来源配置（未按本对象过滤）</h3><p class="visual-boundary">以下仅列工作区来源配置，不表示这些来源都关联当前资产；对象覆盖以表中事实记录为准。</p><div v-for="source in independentRuntime ? [] : data?.sources || []" :key="source.id"><Icon name="integrations"/><strong>{{ source.name }}</strong><span>{{ sourceState(source.status) }}</span><time>{{ source.lastObservedAt ? formatDate(source.lastObservedAt) : '尚无观察时点' }}</time></div><p v-if="independentRuntime || !data?.sources.length" class="visual-empty">当前无可展示的工作区来源配置。来源列表不代表当前对象的采集覆盖。</p></div>
        </section>

        <section v-else-if="presentation.layout === 'classification'" class="visual-panel">
          <div class="visual-panel-heading"><h2>分类版本与采用链</h2><a class="table-link" :href="href('classification')">进入分类台账<Icon name="external"/></a></div>
          <div class="visual-adoption"><ScenarioFactCard title="识别候选" icon="search" :facts="facts" :fact-keys="['classification_candidates']"/><ScenarioFactCard title="人工确认" icon="user" :facts="facts" :fact-keys="['classification_context','classification_record']"/><ScenarioFactCard title="独立发布" icon="reports" :facts="facts" :fact-keys="['classification_publication']"/></div>
          <dl class="visual-classification"><div><dt>数据属性</dt><dd>{{ classification ? assetCategoryLabels[classification.item.asset.category || ''] || '待判定' : '未取得' }}</dd></div><div><dt>企业内部级别</dt><dd>{{ classification ? assetBusinessLevelLabels[classification.item.asset.businessLevel || ''] || '待判定' : '未取得' }}</dd></div><div><dt>法定数据类别</dt><dd>{{ classification ? assetStatutoryCategoryLabels[classification.item.asset.statutoryCategory || 'unknown'] : '未核实' }}</dd></div></dl><p class="visual-boundary">识别候选不自动成为人工确认；内部级别不等于法定类别。新来源不回填旧发布快照。</p>
        </section>

        <section v-else-if="presentation.layout === 'ai-lanes'" class="visual-panel">
          <div class="visual-panel-heading"><h2>已接入业务的三类数据边界</h2><span class="visual-layer">配置声明 / 规则判断 / 来源观察</span></div>
          <div v-for="lane in lanes" :key="lane.name" class="visual-ai-lane"><div class="visual-lane-label"><Icon :name="lane.icon"/><h3>{{ lane.name }}</h3><small>{{ lane.description }}</small></div><ScenarioFactCard title="已有配置声明" :facts="facts" :fact-keys="lane.keys"/><Icon class="visual-lane-arrow" name="arrow"/><section class="visual-lane-observation"><h3>本次技术观察</h3><button v-for="result in lane.results" :key="result.id" type="button" @click="emit('finding',result.id)"><span class="badge" :class="outcomeClass(result.outcome)">{{ scenarioCheckOutcomeLabels[result.outcome] || result.outcome }}</span><strong>{{ result.title }}</strong><small>{{ result.coverage }}</small></button><p v-if="!lane.results.length">本次接口没有逐泳道映射字段。请在下方核对实际返回的技术基线；此维度保持待核实。</p></section></div><section class="visual-ai-returned"><h3>本次实际返回的技术基线</h3><p>当前接口未提供逐泳道映射，以下发现保持原规则与覆盖，不凭标题猜测输入、知识或输出归属。</p><button v-for="item in findings" :key="item.id" class="visual-comparison-record" type="button" @click="emit('finding',item.id)"><strong>{{ item.title }}</strong><span class="badge" :class="outcomeClass(item.outcome)">{{ scenarioCheckOutcomeLabels[item.outcome] || item.outcome }}</span><p>{{ item.observed }}</p><small>{{ item.ruleVersion }} · {{ item.coverage }}</small></button><p v-if="!findings.length" class="visual-empty">尚无本次技术发现。</p></section><p class="visual-boundary">企业 AI 出口策略与平台分类模型设置分别管理；这里只列本次来源实际覆盖的维度，不展示提示词或答复正文。</p>
        </section>

        <section v-else-if="['receivers','outsourcing','suppliers'].includes(presentation.layout)" class="visual-panel">
          <div class="visual-panel-heading"><h2>{{ presentation.layout === 'outsourcing' ? '委托指令与处理证据' : presentation.layout === 'suppliers' ? '供应商与工具接收边界' : '接收方与批准范围对照' }}</h2><span class="visual-layer">登记与实际观察分层</span></div>
          <div class="visual-receiver-comparison"><div><h3>{{ presentation.layout === 'suppliers' ? '配置与接收声明' : '登记 / 批准范围' }}</h3><ScenarioFactCard v-for="key in presentation.keys" :key="key" :title="assessmentFactLabels[key] || key" :facts="facts" :fact-keys="[key]"/></div><Icon name="arrow"/><div><h3>本次来源与差异</h3><button v-for="item in findings" :key="item.id" type="button" class="visual-comparison-record" @click="emit('finding',item.id)"><strong>{{ item.title }}</strong><span class="badge" :class="outcomeClass(item.outcome)">{{ scenarioCheckOutcomeLabels[item.outcome] || item.outcome }}</span><p>{{ item.observed }}</p><small>{{ item.coverage }}</small></button><p v-if="!findings.length" class="visual-empty">未取得本次范围的检查发现。没有观察不代表接收关系已终止或所有调用已覆盖。</p></div></div>
        </section>

        <section v-else-if="presentation.layout === 'timeline'" class="visual-panel">
          <div class="visual-panel-heading"><h2>采用来源事件时间线</h2><button class="table-link" type="button" @click="emit('ledger','evidence')">完整证据清单</button></div>
          <div class="visual-source-lanes"><section v-for="group in sourceGroups" :key="group.source"><h3><Icon name="audit"/>{{ assessmentFactSourceLabel(group.source) }}</h3><ol><li v-for="record in group.records" :key="record.id"><time>{{ record.observedAt ? formatDate(record.observedAt) : '时点未提供' }}</time><strong>{{ record.record }}</strong><p>{{ record.scope }}</p><small>来源引用 {{ record.id }}</small></li></ol></section></div><p v-if="!sourceGroups.length" class="visual-empty">尚无本次采用的来源记录。先选择明确对象与来源窗口，再核对调查线索。</p><p class="visual-boundary">按返回的来源类型分栏、各记录保留自身引用；分栏不表示同一物理来源或因果关联，缺失时间不补造。</p>
        </section>

        <section v-else-if="['actions','exit','retest','revision'].includes(presentation.layout)" class="visual-panel">
          <div class="visual-panel-heading"><h2>{{ {actions:'准确目标与处置回执',exit:'退出核验与尚缺证据',retest:'原检查与新来源采用',revision:'业务修订与检查版本'}[presentation.layout] }}</h2></div>
          <div v-if="presentation.layout === 'exit'" class="visual-exit-chain"><div v-for="label in ['关系终止','授权撤回','来源回执','同目标新观察','返还 / 删除','独立核实']" :key="label"><Icon name="warning"/><strong>{{ label }}</strong><span>需要对应来源证据</span></div></div>
          <div v-if="['retest','revision'].includes(presentation.layout)" class="visual-version-pair"><section><span>原始冻结记录</span><h3>{{ run?.previousRunId ? '关联前次 #' + run.previousRunId : '尚未关联前次运行' }}</h3><p>旧运行的范围、规则与观察继续保留。</p></section><Icon name="arrow"/><section><span>当前采用</span><h3>{{ run ? '运行 #' + run.id : '尚无当前运行' }}</h3><p>{{ run ? scenarioCheckRetestLabels[run.retestState] || run.retestState : '需要实际检查与新来源' }}</p><p v-if="run?.activityRevision">采用活动 v{{ run.activityRevision }}<template v-if="activity"> · 当前登记 v{{ activity.revision }}</template></p><p v-if="run?.assetRevision">采用分类 v{{ run.assetRevision }}</p></section></div>
          <div class="visual-table" role="region" tabindex="0" aria-label="本次发现的处置引用"><table><thead><tr><th>关联发现</th><th>处置与版本</th><th>真实阶段</th><th>来源回执</th></tr></thead><tbody><tr v-for="action in actions" :key="action.actionId"><td>{{ findings.find(f => f.id === action.findingId)?.title || action.findingId }}</td><td><a class="table-link" :href="href('operations/' + action.actionId)">#{{ action.actionId }} · v{{ action.revision }}</a></td><td>{{ controlStatusLabels[action.status] || action.status }}</td><td>{{ action.result?.code || '尚未返回' }}</td></tr></tbody></table></div><p v-if="!actions.length" class="visual-empty">当前运行尚无关联处置。未收到回执、新观察或删除凭证，不能升级为已完成。</p><ScenarioFactCard :title="presentation.layout === 'exit' ? '退出与保存登记' : '范围与来源事实'" :facts="facts" :fact-keys="presentation.keys"/>
        </section>

        <section v-else-if="['packages','procedures'].includes(presentation.layout)" class="visual-panel">
          <div class="visual-panel-heading"><h2>{{ presentation.layout === 'procedures' ? '路径条件与材料要求' : '本次证据包与缺失内容' }}</h2><button class="table-link" type="button" @click="emit('ledger','requirements')">完整依据和程序</button></div>
          <div class="visual-report-list"><article v-for="report in reports" :key="report.key"><h3>{{ report.title }}</h3><span class="badge" :class="report.status === 'available' ? 'status-in_progress' : 'status-needs_work'">{{ scenarioCheckReportLabels[report.status] || report.status }}</span><p>{{ report.coverage }}</p><small>{{ report.basis.title }} · {{ report.basis.clause }} · {{ report.basis.version }}</small><ul><li v-for="missing in report.missingConditions" :key="missing">{{ missing }}</li></ul><details><summary>所需材料与外部程序</summary><ul><li v-for="item in report.requiredDeliverables" :key="item">{{ item }}</li><li v-for="item in report.externalSteps" :key="item">{{ item }}</li></ul></details></article></div><p v-if="!reports.length" class="visual-empty">尚无本次运行返回的报告要求。模板中的参考核查要求不代表实际适用或正式程序完成。</p><ScenarioFactCard v-if="presentation.layout === 'procedures'" title="适用途径待核事实" :facts="facts" :fact-keys="presentation.keys"/>
        </section>

        <section v-else class="visual-panel">
